class Solution {
  public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
    int n = boxes.length;
    long[] weight = new long[n + 1];
    int[] changes =
        new int[n + 2]; // changes[i]: port changes between consecutive boxes among the first i
    for (int i = 1; i <= n; i++) {
      weight[i] = weight[i - 1] + boxes[i - 1][1];
      changes[i] = changes[i - 1] + (i > 1 && boxes[i - 1][0] != boxes[i - 2][0] ? 1 : 0);
    }
    int[] dp = new int[n + 1];
    int[] queue = new int[n + 1];
    int head = 0, tail = 0;
    // candidates j minimise dp[j] - changes[j + 1]
    for (int i = 1; i <= n; i++) {
      int j = i - 1;
      while (tail > head
          && dp[queue[tail - 1]] - changes[queue[tail - 1] + 1] >= dp[j] - changes[j + 1]) tail--;
      queue[tail++] = j;
      while (i - queue[head] > maxBoxes || weight[i] - weight[queue[head]] > maxWeight) head++;
      int best = queue[head];
      dp[i] = dp[best] - changes[best + 1] + changes[i] + 2;
    }
    return dp[n];
  }
}
